44	//     field would hide that duplication. Malformed number syntax still fails
45	//     and is left to the regular parse to report.
46	//   - A document too malformed to keep walking aborts the scan; the regular
47	//     parse then reports the syntax or type error instead, so this check
48	//     never changes how invalid JSON fails.
49	package chainledger
50	
51	import (
52		"bytes"
53		"encoding/json"
54		"errors"
55		"fmt"
56		"strings"
57	)
