func TestScratchBigNumberBeforeCorrupt(t *testing.T) {
	cases := map[string]string{
		"big top-level before corrupt change name":
			`{"note":1e400,"changes":[{"name":"a` + "\xff" + `","upstreams":[]}]}`,
		"big nested unknown before corrupt change name":
			`{"meta":{"x":[1e400,{"y":1e999}]},"changes":[{"name":"a` + "\xff" + `","upstreams":[]}]}`,
		"big in record unknown before name":
