80		// requires the walk to skip the unknown value without consuming it as a
81		// float64 (UseNumber), even when it nests behind objects and arrays.
82		bigPrefixes := map[string]string{
83			"big number opens the plan":           `{"note":1e400,`,
84			"signed big number opens the plan":    `{"note":-1e400,`,
85			"big number nested in unknown object": `{"meta":{"x":[1e400,{"y":1e999}]},`,
86			"big number among unknown array data": `{"bag":[1e400,"z",[2e999,{"k":-1e400}]],`,
87			"repeated unknown field with numbers": `{"note":1e400,"note":2e999,`,
88		}
