288				}
289				if _, ok := graph["源�"]; ok {
290					t.Fatal("the dataset really named 源� must be gone after apply")
291				}
292				if _, ok := graph["keep"]; !ok {
293					t.Fatal("the unrelated dataset keep must survive")
294				}
295			})
