299				}
300				if _, ok := graph["keep"]; !ok {
301					t.Fatal("the unrelated dataset keep must survive")
302				}
303	
304				stdout, stderr, exit = runBatchCLI(t, "apply", applyGraph, planPath)
305				if exit != 0 {
306					t.Fatalf("re-apply exit = %d, stderr = %s", exit, stderr)
307				}
308				if got := mustParseReport(t, stdout).RemovedDatasets; len(got) != 0 {
309					t.Errorf("re-apply must report no removals, got %v", got)
310				}
311			})
312		}
313	}
