315	// TestCLIUnknownFieldsDoNotChangeReportOrGraph: for a plan whose business
316	// names are all legal, adding or removing the additional information
317	// (oversized numbers at the top level, nested in unknown objects/arrays, or
318	// inside change records) changes neither preview's report bytes nor apply's
319	// report bytes and the final graph file.
320	func TestCLIUnknownFieldsDoNotChangeReportOrGraph(t *testing.T) {
321		graphContent := `{"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]},{"name":"源�","upstreams":[]}]}`
322		plans := map[string]string{
323			"plain": `{"changes":[{"name":"B","upstreams":["源�"]}],"removals":["A"]}`,
324			"big number at top": `{"note":1e400,` +
325				`"changes":[{"name":"B","upstreams":["源�"]}],"removals":["A"]}`,
326			"big numbers nested everywhere": `{"meta":{"x":[1e400,{"y":1e999}]},"changes":[` +
327				`{"name":"B","upstreams":["源�"],"vals":[1e999,-1e400],"note":{}}],` +
328				`"removals":["A"],"tail":[2e400]}`,
329		}
330	
331		// Preview reports must be byte-identical across the plan spellings.
332		var basePreview string
333		for name, planContent := range plans {
334			graphPath := writeFile(t, filepath.Join(name+"-preview-graph.json"), graphContent)
335			planPath := writeFile(t, filepath.Join(name+"-plan.json"), planContent)
336			stdout, stderr, exit := runBatchCLI(t, "preview", graphPath, planPath)
337			if exit != 0 {
338				t.Fatalf("preview %s exit = %d, stderr = %s", name, exit, stderr)
339			}
340			if basePreview == "" {
341				basePreview = stdout
342			} else if stdout != basePreview {
343				t.Fatalf("preview %s report differs from plain:\n%s\n%s", name, stdout, basePreview)
344			}
345		}
346	
347		// Apply: identical reports and identical resulting graph bytes.
348		var baseApply, baseGraph string
349		for name, planContent := range plans {
350			graphPath := writeFile(t, filepath.Join(name+"-apply-graph.json"), graphContent)
351			planPath := writeFile(t, filepath.Join(name+"-apply-plan.json"), planContent)
352			stdout, stderr, exit := runBatchCLI(t, "apply", graphPath, planPath)
353			if exit != 0 {
354				t.Fatalf("apply %s exit = %d, stderr = %s", name, exit, stderr)
355			}
356			finalGraph := readFile(t, graphPath)
357			if baseApply == "" {
358				baseApply, baseGraph = stdout, finalGraph
359			} else {
360				if stdout != baseApply {
361					t.Fatalf("apply %s report differs from plain:\n%s\n%s", name, stdout, baseApply)
362				}
363				if finalGraph != baseGraph {
364					t.Fatalf("apply %s graph bytes differ from plain:\n%s\n%s", name, finalGraph, baseGraph)
365				}
366			}
367		}
368	}
